CREATE proc [dbo].[UspSelectItemUnit] @ItemId as Int as  declare @IsExist as bit set @IsExist = 0; select @IsExist = ItemId from warehouse_store where ItemId = @ItemId if @IsExist = 0  begin select @IsExist = ItemId from dbo.PurchaseOrderDetail_Store where ItemId = @ItemId if @IsExist = 0  begin select @IsExist = ItemId from dbo.DemandSheetDetail_Store where ItemId = @ItemId if @IsExist = 0  begin select @IsExist = ItemId from dbo.DemandSheetDetail_Branch where ItemId = @ItemId if @IsExist = 0  begin select @IsExist = IngredientId from dbo.RecipeDetail where IngredientId = @ItemId end  end end end  select @IsExist as A;